CREATE TABLE idempotency_record(actor_id BIGINT NOT NULL,operation VARCHAR(40) NOT NULL,request_key VARCHAR(80) NOT NULL,request_hash CHAR(64) NOT NULL,response_json JSON NOT NULL,PRIMARY KEY(actor_id,operation,request_key));
CREATE TABLE outbox_event(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id CHAR(36) NOT NULL UNIQUE,target VARCHAR(40) NOT NULL,event_type VARCHAR(60) NOT NULL,payload JSON NOT NULL,status VARCHAR(20) NOT NULL,retry_count INT NOT NULL DEFAULT 0,next_retry_at DATETIME(3) NOT NULL,lease_until DATETIME(3),published_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX ix_dispatch(status,next_retry_at));
CREATE TABLE consumed_event(event_id CHAR(36) PRIMARY KEY,consumed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE audit_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT,action VARCHAR(60) NOT NULL,resource_id VARCHAR(60),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));

CREATE TABLE community(id BIGINT PRIMARY KEY,name VARCHAR(100) NOT NULL);
CREATE TABLE vehicle(id BIGINT PRIMARY KEY,user_id BIGINT NOT NULL,plate VARCHAR(20) NOT NULL UNIQUE,INDEX ix_owner(user_id));
CREATE TABLE parking_space(id BIGINT PRIMARY KEY,community_id BIGINT NOT NULL,owner_id BIGINT NOT NULL,name VARCHAR(60) NOT NULL,hourly_fen BIGINT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,occupied_reservation_id BIGINT,FOREIGN KEY(community_id) REFERENCES community(id));
CREATE TABLE share_window(id BIGINT PRIMARY KEY,space_id BIGINT NOT NULL,start_at DATETIME(3) NOT NULL,end_at DATETIME(3) NOT NULL,FOREIGN KEY(space_id) REFERENCES parking_space(id),CHECK(end_at>start_at));
CREATE TABLE reservation_order(id BIGINT PRIMARY KEY,user_id BIGINT NOT NULL,vehicle_id BIGINT NOT NULL,space_id BIGINT NOT NULL,community_id BIGINT NOT NULL,plate VARCHAR(20) NOT NULL,hourly_fen BIGINT NOT NULL,start_at DATETIME(3) NOT NULL,end_at DATETIME(3) NOT NULL,pay_deadline DATETIME(3) NOT NULL,prepay_fen BIGINT NOT NULL,overtime_fen BIGINT NOT NULL DEFAULT 0,status VARCHAR(24) NOT NULL,entered_at DATETIME(3),exited_at DATETIME(3),version INT NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX ix_space_interval(space_id,start_at,end_at,status),INDEX ix_vehicle_interval(vehicle_id,start_at,end_at,status),INDEX ix_owner(user_id),CHECK(end_at>start_at));
